{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/slot-grid.json
    Delivery windows by day: each day lists its windows as radio chips; closed windows are disabled and struck through. One radio group (`name`) across all days. Static markup.
    Props (p): days, name, item. *}
{var $v_days = ($p['days'] ?? null)}
{var $v_name = ($p['name'] ?? null)}
{var $v_item = ($p['item'] ?? 'card')}
{capture $c_10}
  {foreach og_l($v_days) as $v_d}
    {capture $c_9}
      {capture $c_3}
        {capture $c_1}
          {=og_text(og_get($v_d, ['title']))}
        {/capture}
        {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'children' => (string) $c_1])|noescape}
        {capture $c_2}
          {=og_text(og_get($v_d, ['note']))}
        {/capture}
        {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
      {/capture}
      {=og_include('compose/Group.latte', ['gap' => '4', 'align' => 'baseline', 'justify' => 'between', 'class' => 'flex-wrap', 'children' => (string) $c_3])|noescape}
      {capture $c_8}
        {foreach og_l(og_get($v_d, ['slots'])) as $v_s}
          {capture $c_5}
            {=og_include('compose/Radio.latte', ['name' => og_s($v_name), 'value' => og_s(og_tpl('{0} {1}', [og_get($v_d, ['id']), $v_s]))])|noescape}
            {capture $c_4}
              {=og_text($v_s)}
            {/capture}
            {=og_include('compose/Inline.latte', ['children' => (string) $c_4])|noescape}
          {/capture}
          {=og_include('compose/Label.latte', ['class' => 'flex items-center gap-2 rounded px-4 py-2 text-sm inset-ring inset-ring-border has-checked:bg-muted has-checked:inset-ring-foreground', 'children' => (string) $c_5])|noescape}
        {/foreach}
        {foreach og_l(og_get($v_d, ['closed'])) as $v_s}
          {capture $c_7}
            {=og_include('compose/Radio.latte', ['name' => og_s($v_name), 'value' => og_s(og_tpl('{0} {1}', [og_get($v_d, ['id']), $v_s])), 'disabled' => true])|noescape}
            {capture $c_6}
              {=og_text($v_s)}
            {/capture}
            {=og_include('compose/Inline.latte', ['children' => (string) $c_6])|noescape}
          {/capture}
          {=og_include('compose/Label.latte', ['class' => og_s(og_cnv(['flex items-center gap-2 rounded px-4 py-2 text-sm inset-ring inset-ring-border has-checked:bg-muted has-checked:inset-ring-foreground', 'text-muted-foreground line-through'])), 'children' => (string) $c_7])|noescape}
        {/foreach}
      {/capture}
      {=og_include('compose/Box.latte', ['class' => 'grid grid-cols-2 gap-2 sm:grid-cols-3', 'children' => (string) $c_8])|noescape}
    {/capture}
    {=og_include('compose/Stack.latte', ['gap' => '4', 'class' => og_s((og_t(og_eq($v_item, 'card')) ? 'rounded bg-card inset-ring inset-ring-border p-4' : 'border-b border-border pb-4')), 'attrs' => og_attrs(['data-testid', 'day']), 'children' => (string) $c_9])|noescape}
  {/foreach}
{/capture}
{=og_include('compose/Stack.latte', ['gap' => '4', 'align' => 'stretch', 'attrs' => og_attrs(['data-testid', 'days']), 'children' => (string) $c_10])|noescape}
